-- Exam engine schema (docs/plans/EXAM-PLAN.md 2.2, 2.3). Generated by Prisma from schema.prisma, plus this first
-- statement by hand: the new NOT NULL columns (lineage_id, position, question_count, content_version, end_reason,
-- violation_count) have no meaningful backfill, and no product code has written questions, attempts or submissions
-- before this migration. On *_test databases, prepare-test-db.mjs empties the exam tables first (EXAM-PLAN 2.3).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "questions") OR EXISTS (SELECT 1 FROM "attempts") OR EXISTS (SELECT 1 FROM "submissions") THEN
    RAISE EXCEPTION 'exam_engine migration stopped: questions, attempts or submissions already hold rows. Nothing was changed. See docs/plans/EXAM-PLAN.md section 2.3 before going on.';
  END IF;
END
$$;

